mapper.select:
SELECT * FROM rec_interview

    deleted = 0

        AND candidate_id = #{params.candidateId}


        AND job_position_id = #{params.jobPositionId}


        AND status = #{params.status}


        AND type = #{params.type}


        AND candidate_name LIKE CONCAT('%', #{params.candidateName}, '%')


        AND (

                JSON_CONTAINS(interviewer_ids, CAST(#{id} AS JSON))

        )


        AND scheduled_time >= #{params.startDate}


        AND scheduled_time <= #{params.endDate}


ORDER BY create_time DESC

SELECT COUNT(*) AS total, 0 AS today, COALESCE(SUM(CASE WHEN result = 0 THEN 1 ELSE 0 END), 0) AS passed, COALESCE(SUM(CASE WHEN status = 3 THEN 1 ELSE 0 END), 0) AS cancelled FROM rec_interview WHERE deleted = 0
AND create_time >= #{start}
AND create_time < #{end}

SELECT id, real_name FROM smart_recruit_system.sys_user
WHERE id IN

    #{id}
